CREATE TABLE invite_capabilities (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), token_hash TEXT NOT NULL UNIQUE, role TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT, exchanged_at TEXT) STRICT;
CREATE TABLE participant_sessions (id_hash TEXT PRIMARY KEY, participation_id TEXT NOT NULL REFERENCES guest_participations(id), community_id TEXT NOT NULL REFERENCES communities(id), event_id TEXT NOT NULL REFERENCES events(id), role TEXT NOT NULL, assurance TEXT NOT NULL CHECK(assurance IN ('invite','open-public')), expires_at TEXT NOT NULL, revoked_at TEXT) STRICT;
CREATE TABLE event_eligible_songs (event_id TEXT NOT NULL REFERENCES events(id), song_id TEXT NOT NULL REFERENCES canonical_songs(id), added_at TEXT NOT NULL, PRIMARY KEY(event_id,song_id)) STRICT;
CREATE TABLE event_choice_config (event_id TEXT PRIMARY KEY REFERENCES events(id), proposal_policy TEXT NOT NULL DEFAULT 'immediate' CHECK(proposal_policy IN ('immediate','editorial')), show_live_totals INTEGER NOT NULL DEFAULT 0, demand_weight REAL NOT NULL DEFAULT .7, feasibility_weight REAL NOT NULL DEFAULT .3) STRICT;
CREATE TRIGGER event_choice_config_seed AFTER INSERT ON events BEGIN INSERT INTO event_choice_config(event_id) VALUES (NEW.id); END;
INSERT INTO event_choice_config(event_id) SELECT id FROM events;
CREATE TABLE participant_ballots (participation_id TEXT PRIMARY KEY REFERENCES guest_participations(id), event_id TEXT NOT NULL REFERENCES events(id), current_revision INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'open' CHECK(state IN ('open','closed','reopened')), candidate_order_json TEXT NOT NULL CHECK(json_valid(candidate_order_json)), rankings_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(rankings_json))) STRICT;
CREATE TABLE choice_receipts (community_id TEXT NOT NULL REFERENCES communities(id), operation_id TEXT NOT NULL, request_hash TEXT NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), created_at TEXT NOT NULL, PRIMARY KEY(community_id,operation_id)) STRICT;
CREATE TABLE choice_proposals (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), participation_id TEXT NOT NULL REFERENCES guest_participations(id), title TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('submitted','eligible','rejected')), created_at TEXT NOT NULL) STRICT;
CREATE TABLE proposal_receipts (participation_id TEXT NOT NULL REFERENCES guest_participations(id), operation_id TEXT NOT NULL, request_hash TEXT NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), PRIMARY KEY(participation_id,operation_id)) STRICT;
CREATE TABLE participation_claims (participation_id TEXT PRIMARY KEY REFERENCES guest_participations(id), account_id TEXT NOT NULL UNIQUE, proof_reference TEXT NOT NULL, claimed_at TEXT NOT NULL) STRICT;
